style.css:
@-moz-document url-prefix("http://"), url-prefix("https://") {
:root{
    --cr-bg: #FBF7F2;
    --cr-surface: #FFFDFB;
    --cr-text: #2B2A28;
    --cr-muted: #9F988F;
    --cr-accent: #C9A87C;
    --cr-accent-2: #EFDCC0;
    --cr-radius: 10px;
    --cr-shadow: 0 6px 18px rgba(43,42,40,0.06);
  }

  /* Page background and base text color */
  html, body {
    background-color: var(--cr-bg) !important;
    color: var(--cr-text) !important;
    -webkit-font-smoothing: antialiased !important;
    -moz-osx-font-smoothing: grayscale !important;
  }

  /* Make main containers warmer and pillowy */
  header, nav, main, article, section, aside, footer, .container, .content, .site {
    background-color: transparent !important;
    color: inherit !important;
  }

  /* Gentle surfaces for common panels/cards */
  .card, .panel, .box, [role="main"] > div, .post, .article, .comment, .widget {
    background: linear-gradient(180deg, var(--cr-surface), #FFFDF7) !important;
    border-radius: var(--cr-radius) !important;
    box-shadow: var(--cr-shadow) !important;
    border: 1px solid rgba(43,42,40,0.03) !important;
  }

  /* Links and accents */
  a, a:link, a:visited {
    color: var(--cr-accent) !important;
    text-decoration: underline !important;
  }
  a:hover, a:focus {
    color: #A77649 !important;
    text-decoration: none !important;
  }

  /* Buttons */
  button, input[type="button"], input[type="submit"], .btn {
    background: linear-gradient(180deg, var(--cr-accent), #B88954) !important;
    color: #fff !important;
    border: 0 !important;
    border-radius: 12px !important;
    padding: 8px 12px !important;
    box-shadow: 0 6px 14px rgba(200,160,110,0.14) !important;
  }

  /* Inputs and textareas */
  input, textarea, select {
    background: linear-gradient(180deg, #FFFDF9, #FEFBF7) !important;
    border: 1px solid rgba(43,42,40,0.06) !important;
    color: var(--cr-text) !important;
    border-radius: 8px !important;
    padding: 8px 10px !important;
  }
  input:focus, textarea:focus, select:focus {
    outline: none !important;
    box-shadow: 0 0 0 4px rgba(201,168,124,0.12) !important;
  }

  /* Muted text */
  small, .meta, .muted, .subtitle {
    color: var(--cr-muted) !important;
  }

  /* Reduce harsh shadows and borders on many sites */
  img, picture, svg { filter: none !important; }
  * {
    transition: background-color .12s ease, color .12s ease !important;
  }

  /* Keep layout intact: avoid globally changing widths or display types */
  :not(input):not(textarea):not(button):not(select) {
    border-radius: inherit !important;
  }

  /* Optional: slightly round images that look like avatars (non-invasive) */
  img.avatar, .avatar, [class*="avatar"] img, img.profile {
    border-radius: 10px !important;
  }

  /* Disable the style on known interactive widgets to avoid breakage */
  /* Override by adding your own exceptions if needed */
  .gm-style, .leaflet-container, .ace_editor, iframe, canvas {
    background: initial !important;
    filter: none !important;
    box-shadow: none !important;
  }
}
